1	package classification
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
8		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
9	)
10	
11	// AuthzResult represents the result of authz signal classification.
12	// It contains only the matched role names — the decision engine uses these
13	// to select models via modelRefs.
14	type AuthzResult struct {
15		// MatchedRules contains the role names from all matched role bindings.
16		// These are the Role field values, not the binding Name field.
17		MatchedRules []string
18	}
19	
20	// normalizedBinding is the internal representation with Kind/Name already normalized.
21	// This avoids repeated string normalization at request time.
22	type normalizedBinding struct {
23		name     string // binding name (for logs)
24		role     string // role name (emitted as signal)
25		subjects []normalizedSubject
26	}
27	
28	type normalizedSubject struct {
29		kind string // "user" or "group" (already lowercased)
30		name string // already trimmed
31	}
32	
33	// AuthzClassifier evaluates user identity and group membership against RBAC role bindings.
34	// It follows the Kubernetes RoleBinding pattern:
35	//   - Subject  → user ID + groups (from auth backend: Authorino, Envoy Gateway JWT, etc.)
36	//   - Role     → RoleBinding.Role (emitted as the signal name)
37	//   - Permission → decision engine modelRefs (not this classifier's concern)
38	type AuthzClassifier struct {
39		bindings []normalizedBinding
40	}
41	
42	// NewAuthzClassifier creates a new AuthzClassifier from RBAC role bindings.
43	// All validation and normalization happens here at startup. If this function returns
44	// without error, Classify() is guaranteed to work correctly at request time.
45	//
46	// Validates at startup:
47	//   - Binding name must not be empty
48	//   - Binding name must be unique across all bindings
49	//   - Role must not be empty
50	//   - At least one subject must be specified
51	//   - Each subject must have kind "User" or "Group" (case-insensitive)
52	//   - Each subject must have a non-empty name (whitespace-only is rejected)
53	//
54	// Normalizes at startup:
55	//   - Subject.Kind is lowercased and trimmed
56	//   - Subject.Name is trimmed (preserving original case for exact matching)
57	func NewAuthzClassifier(bindings []config.RoleBinding) (*AuthzClassifier, error) {
58		seenNames := make(map[string]bool, len(bindings))
59		normalized := make([]normalizedBinding, 0, len(bindings))
60	
61		for _, rb := range bindings {
62			if rb.Name == "" {
63				return nil, fmt.Errorf("role_bindings: binding with empty name is not allowed")
64			}
65			if seenNames[rb.Name] {
66				return nil, fmt.Errorf("role_bindings: duplicate binding name %q — "+
67					"each binding must have a unique name for audit log clarity", rb.Name)
68			}
69			seenNames[rb.Name] = true
70	
71			if rb.Role == "" {
72				return nil, fmt.Errorf("role_bindings: binding %q has empty role — "+
73					"set the role field to the name used in decision conditions (type: \"authz\", name: \"<role>\")", rb.Name)
74			}
75			if len(rb.Subjects) == 0 {
76				return nil, fmt.Errorf("role_bindings: binding %q has no subjects — "+
77					"add at least one subject with kind User or Group", rb.Name)
78			}
79	
80			nb := normalizedBinding{
81				name:     rb.Name,
82				role:     rb.Role,
83				subjects: make([]normalizedSubject, 0, len(rb.Subjects)),
84			}
85	
86			for i, s := range rb.Subjects {
87				kind := strings.ToLower(strings.TrimSpace(s.Kind))
88				if kind != "user" && kind != "group" {
89					return nil, fmt.Errorf("role_bindings: binding %q subject[%d] has invalid kind %q — "+
90						"must be \"User\" or \"Group\"", rb.Name, i, s.Kind)
91				}
92				name := strings.TrimSpace(s.Name)
93				if name == "" {
94					return nil, fmt.Errorf("role_bindings: binding %q subject[%d] (kind: %s) has empty name — "+
95						"the name must match the value your auth backend injects in the identity headers (configured via authz.identity)",
96						rb.Name, i, s.Kind)
97				}
98				nb.subjects = append(nb.subjects, normalizedSubject{kind: kind, name: name})
99			}
100	
101			normalized = append(normalized, nb)
102		}
103	
104		return &AuthzClassifier{bindings: normalized}, nil
105	}
106	
107	// Classify evaluates the RBAC role bindings against the user identity and groups.
108	//
109	// Match logic: a binding matches if ANY of its subjects match:
110	//   - kind: "user"  → matches if subject.name == userID
111	//   - kind: "group" → matches if subject.name is in userGroups
112	//
113	// When a binding matches, its role is emitted as the signal name.
114	// Multiple bindings can match. If multiple bindings grant the same role, it is deduplicated.
115	//
116	// Returns an error if userID is empty and role bindings are configured — this prevents
117	// silent bypass when ext_authz fails to inject the user identity header.
118	func (c *AuthzClassifier) Classify(userID string, userGroups []string) (*AuthzResult, error) {
119		if len(c.bindings) == 0 {
120			return &AuthzResult{}, nil
121		}
122	
123		if userID == "" {
124			return nil, fmt.Errorf("authz signal: user identity header is empty but %d role_bindings are configured — "+
125				"ensure your auth backend injects the user identity header (check authz.identity.user_id_header config); "+
126				"refusing to evaluate without user identity (no silent bypass allowed)", len(c.bindings))
127		}
128	
129		// Deduplicate roles (multiple bindings can grant the same role)
130		roleSet := make(map[string]bool)
131		var matchedRoles []string
132	
133		for _, rb := range c.bindings {
134			matched := false
135	
136			for _, s := range rb.subjects {
137				// Kind and Name are already normalized at startup — no runtime normalization needed
138				switch s.kind {
139				case "user":
140					if s.name == userID {
141						matched = true
142						logging.Infof("[Authz Signal] Binding %q matched: subject User %q == user ID %q → role %q",
143							rb.name, s.name, userID, rb.role)
144					}
145				case "group":
146					for _, ug := range userGroups {
147						if s.name == ug {
148							matched = true
149							logging.Infof("[Authz Signal] Binding %q matched: subject Group %q in user groups → role %q",
150								rb.name, s.name, rb.role)
151							break
152						}
153					}
154				default:
155					// Cannot happen: NewAuthzClassifier validates kind at startup.
156					// If it does happen, it's a programming error — fail loudly.
157					panic(fmt.Sprintf("authz classifier: unexpected subject kind %q in binding %q — "+
158						"this is a bug: NewAuthzClassifier should have rejected this at startup", s.kind, rb.name))
159				}
160				if matched {
161					break
162				}
163			}
164	
165			if matched && !roleSet[rb.role] {
166				roleSet[rb.role] = true
167				matchedRoles = append(matchedRoles, rb.role)
168			}
169		}
170	
171		if len(matchedRoles) == 0 {
172			logging.Infof("[Authz Signal] No roles matched for user %q (groups: %v)", userID, userGroups)
173		} else {
174			logging.Infof("[Authz Signal] Matched %d roles for user %q: %v", len(matchedRoles), userID, matchedRoles)
175		}
176	
177		return &AuthzResult{
178			MatchedRules: matchedRoles,
179		}, nil
180	}
181	
182	// ParseUserGroups parses a comma-separated groups header value into a slice of group names.
183	// Whitespace around group names is trimmed. Empty strings are excluded.
184	func ParseUserGroups(headerValue string) []string {
185		if headerValue == "" {
186			return nil
187		}
188		parts := strings.Split(headerValue, ",")
189		var groups []string
190		for _, p := range parts {
191			g := strings.TrimSpace(p)
192			if g != "" {
193				groups = append(groups, g)
194			}
195		}
196		return groups
197	}
