1	package ratelimit
2	
3	import (
4		"strings"
5		"sync"
6		"time"
7	
8		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
9	)
10	
11	// LocalLimiter is an in-process rate limiter inspired by the Envoy AI Gateway's
12	// usage-based rate limiting. It supports two rule types:
13	//
14	//   - requests_per_unit (RPM): classic request counting per time window
15	//   - tokens_per_unit  (TPM): token budget tracking (AI Gateway-style)
16	//
17	// Rules are matched by user/group/model patterns. Token usage is reported
18	// after response via Report() to decrement token budgets.
19	//
20	// This provider uses sliding window counters keyed by a composite of
21	// user+model+rule, providing per-user per-model granularity without
22	// requiring an external service.
23	type LocalLimiter struct {
24		rules   []Rule
25		buckets sync.Map // key → *bucket
26	}
27	
28	// Rule defines a single rate limit rule.
29	type Rule struct {
30		Name            string
31		Match           RuleMatch
32		RequestsPerUnit int
33		TokensPerUnit   int
34		Unit            time.Duration
35	}
36	
37	// RuleMatch specifies which requests a rule applies to.
38	// Empty string matches everything; "*" is an explicit wildcard.
39	type RuleMatch struct {
40		User  string
41		Group string
42		Model string
43	}
44	
45	type bucket struct {
46		mu        sync.Mutex
47		count     int64
48		windowEnd time.Time
49		unit      time.Duration
50		limit     int64
51	}
52	
53	// NewLocalLimiter creates a local limiter with the given rules.
54	func NewLocalLimiter(rules []Rule) *LocalLimiter {
55		return &LocalLimiter{rules: rules}
56	}
57	
58	func (l *LocalLimiter) Name() string {
59		return "local-limiter"
60	}
61	
62	// Check evaluates all matching rules. If any rule's budget is exhausted,
63	// the request is denied.
64	func (l *LocalLimiter) Check(ctx Context) (*Decision, error) {
65		now := time.Now()
66	
67		var mostRestrictiveRemaining int64 = -1
68		var mostRestrictiveLimit int64 = -1
69		var earliestReset time.Time
70	
71		for i := range l.rules {
72			rule := &l.rules[i]
73			if !l.ruleMatches(rule, ctx) {
74				continue
75			}
76	
77			if rule.RequestsPerUnit > 0 {
78				key := l.bucketKey(rule.Name, ctx.UserID, ctx.Model, "rpm")
79				b := l.getOrCreateBucket(key, int64(rule.RequestsPerUnit), rule.Unit)
80				allowed, remaining, resetAt := b.tryConsume(1, now)
81				if !allowed {
82					return &Decision{
83						Allowed:    false,
84						Remaining:  remaining,
85						Limit:      int64(rule.RequestsPerUnit),
86						ResetAt:    resetAt,
87						RetryAfter: time.Until(resetAt),
88						Provider:   l.Name(),
89					}, nil
90				}
91				if mostRestrictiveRemaining < 0 || remaining < mostRestrictiveRemaining {
92					mostRestrictiveRemaining = remaining
93				}
94				if mostRestrictiveLimit < 0 || int64(rule.RequestsPerUnit) < mostRestrictiveLimit {
95					mostRestrictiveLimit = int64(rule.RequestsPerUnit)
96				}
97				if earliestReset.IsZero() || resetAt.Before(earliestReset) {
98					earliestReset = resetAt
99				}
100			}
101	
102			if rule.TokensPerUnit > 0 {
103				key := l.bucketKey(rule.Name, ctx.UserID, ctx.Model, "tpm")
104				b := l.getOrCreateBucket(key, int64(rule.TokensPerUnit), rule.Unit)
105				cost := int64(ctx.TokenCount)
106				if cost <= 0 {
107					cost = 0
108				}
109				allowed, remaining, resetAt := b.tryConsume(cost, now)
110				if !allowed {
111					return &Decision{
112						Allowed:    false,
113						Remaining:  remaining,
114						Limit:      int64(rule.TokensPerUnit),
115						ResetAt:    resetAt,
116						RetryAfter: time.Until(resetAt),
117						Provider:   l.Name(),
118					}, nil
119				}
120				if mostRestrictiveRemaining < 0 || remaining < mostRestrictiveRemaining {
121					mostRestrictiveRemaining = remaining
122				}
123				if mostRestrictiveLimit < 0 || int64(rule.TokensPerUnit) < mostRestrictiveLimit {
124					mostRestrictiveLimit = int64(rule.TokensPerUnit)
125				}
126				if earliestReset.IsZero() || resetAt.Before(earliestReset) {
127					earliestReset = resetAt
128				}
129			}
130		}
131	
132		if mostRestrictiveRemaining < 0 {
133			mostRestrictiveRemaining = 0
134		}
135		if mostRestrictiveLimit < 0 {
136			mostRestrictiveLimit = 0
137		}
138	
139		return &Decision{
140			Allowed:   true,
141			Remaining: mostRestrictiveRemaining,
142			Limit:     mostRestrictiveLimit,
143			ResetAt:   earliestReset,
144			Provider:  l.Name(),
145		}, nil
146	}
147	
148	// Report records actual token usage from LLM responses for TPM rules.
149	// This adjusts the token budget based on actual usage rather than the
150	// estimated input token count used during Check().
151	func (l *LocalLimiter) Report(ctx Context, usage TokenUsage) error {
152		for i := range l.rules {
153			rule := &l.rules[i]
154			if rule.TokensPerUnit <= 0 || !l.ruleMatches(rule, ctx) {
155				continue
156			}
157	
158			key := l.bucketKey(rule.Name, ctx.UserID, ctx.Model, "tpm")
159			b := l.getOrCreateBucket(key, int64(rule.TokensPerUnit), rule.Unit)
160	
161			// The Check() already consumed estimated input tokens.
162			// Now add the output tokens (the part we didn't know during Check).
163			additionalTokens := int64(usage.OutputTokens)
164			if additionalTokens > 0 {
165				b.consumeOnly(additionalTokens, time.Now())
166				logging.Debugf("Rate limit report: rule=%s user=%s model=%s output_tokens=%d",
167					rule.Name, ctx.UserID, ctx.Model, additionalTokens)
168			}
169		}
170		return nil
171	}
172	
173	func (l *LocalLimiter) ruleMatches(rule *Rule, ctx Context) bool {
174		if rule.Match.User != "" && rule.Match.User != "*" && rule.Match.User != ctx.UserID {
175			return false
176		}
177		if rule.Match.Model != "" && rule.Match.Model != "*" && rule.Match.Model != ctx.Model {
178			return false
179		}
180		if rule.Match.Group != "" && rule.Match.Group != "*" {
181			matched := false
182			for _, g := range ctx.Groups {
183				if g == rule.Match.Group {
184					matched = true
185					break
186				}
187			}
188			if !matched {
189				return false
190			}
191		}
192		return true
193	}
194	
195	func (l *LocalLimiter) bucketKey(ruleName, userID, model, kind string) string {
196		return strings.Join([]string{ruleName, userID, model, kind}, "|")
197	}
198	
199	func (l *LocalLimiter) getOrCreateBucket(key string, limit int64, unit time.Duration) *bucket {
200		if v, ok := l.buckets.Load(key); ok {
201			return v.(*bucket)
202		}
203		b := &bucket{limit: limit, unit: unit}
204		actual, _ := l.buckets.LoadOrStore(key, b)
205		return actual.(*bucket)
206	}
207	
208	// tryConsume attempts to consume `cost` from the bucket.
209	// Returns (allowed, remaining, windowEnd).
210	func (b *bucket) tryConsume(cost int64, now time.Time) (bool, int64, time.Time) {
211		b.mu.Lock()
212		defer b.mu.Unlock()
213	
214		if now.After(b.windowEnd) {
215			b.count = 0
216			b.windowEnd = now.Add(b.unit)
217		}
218	
219		remaining := b.limit - b.count
220		if cost > remaining {
221			return false, remaining, b.windowEnd
222		}
223	
224		b.count += cost
225		return true, b.limit - b.count, b.windowEnd
226	}
227	
228	// consumeOnly decrements the bucket without checking. Used for post-response
229	// token reporting where we must track usage even if it goes negative.
230	func (b *bucket) consumeOnly(cost int64, now time.Time) {
231		b.mu.Lock()
232		defer b.mu.Unlock()
233	
234		if now.After(b.windowEnd) {
235			b.count = 0
236			b.windowEnd = now.Add(b.unit)
237		}
238	
239		b.count += cost
240	}
241	
242	// ParseUnit converts a unit string to a time.Duration.
243	func ParseUnit(unit string) time.Duration {
244		switch strings.ToLower(unit) {
245		case "second":
246			return time.Second
247		case "minute":
248			return time.Minute
249		case "hour":
250			return time.Hour
251		case "day":
252			return 24 * time.Hour
253		default:
254			return time.Minute
255		}
256	}
