package extproc

import (
	"fmt"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/authz"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/ratelimit"
)

// knownAuthzProviderTypes is the set of valid provider type strings.
var knownAuthzProviderTypes = map[string]bool{
	"header-injection": true,
	"static-config":    true,
}

// knownRateLimitProviderTypes is the set of valid rate limit provider type strings.
var knownRateLimitProviderTypes = map[string]bool{
	"envoy-ratelimit": true,
	"local-limiter":   true,
}

// buildCredentialResolver constructs the credential provider chain from config.
func buildCredentialResolver(cfg *config.RouterConfig) *authz.CredentialResolver {
	authzCfg := cfg.Authz

	if len(authzCfg.Providers) == 0 {
		resolver := buildDefaultCredentialResolver(cfg, true)
		return resolver
	}

	validationErrors := validateAuthzProviders(authzCfg.Providers)
	if len(validationErrors) > 0 {
		logValidationErrors("Authz", validationErrors)
		logging.Errorf("Authz config has %d validation error(s) — using default chain. FIX YOUR CONFIG.", len(validationErrors))
		resolver := buildDefaultCredentialResolver(cfg, false)
		return resolver
	}

	providers := createAuthzProviders(cfg)
	resolver := authz.NewCredentialResolver(providers...)
	resolver.SetFailOpen(authzCfg.FailOpen)

	if authzCfg.FailOpen {
		logging.Warnf("Authz: fail_open=true — requests without credentials will pass")
	}
	logging.Infof("Authz: chain=%v, fail_open=%v, user_id_header=%q, user_groups_header=%q",
		resolver.ProviderNames(), authzCfg.FailOpen,
		cfg.Authz.Identity.GetUserIDHeader(), cfg.Authz.Identity.GetUserGroupsHeader())
	return resolver
}

func buildDefaultCredentialResolver(cfg *config.RouterConfig, failOpen bool) *authz.CredentialResolver {
	resolver := authz.NewCredentialResolver(
		authz.NewHeaderInjectionProvider(authz.DefaultHeaderMap()),
		authz.NewStaticConfigProvider(cfg),
	)
	resolver.SetFailOpen(failOpen)
	return resolver
}

func validateAuthzProviders(providers []config.AuthzProviderConfig) []string {
	validationErrors := make([]string, 0)
	for i, provider := range providers {
		validationErrors = append(validationErrors, validateAuthzProvider(i, provider)...)
	}
	return validationErrors
}

func validateAuthzProvider(index int, provider config.AuthzProviderConfig) []string {
	validationErrors := make([]string, 0)
	if !knownAuthzProviderTypes[provider.Type] {
		validationErrors = append(
			validationErrors,
			fmt.Sprintf(
				"authz.providers[%d]: unknown type %q (valid types: header-injection, static-config)",
				index,
				provider.Type,
			),
		)
	}

	if provider.Type != "header-injection" || len(provider.Headers) == 0 {
		return validationErrors
	}

	for providerName, header := range provider.Headers {
		if header == "" {
			validationErrors = append(
				validationErrors,
				fmt.Sprintf(
					"authz.providers[%d].headers: provider %q has empty header name",
					index,
					providerName,
				),
			)
		}
	}
	return validationErrors
}

func createAuthzProviders(cfg *config.RouterConfig) []authz.Provider {
	providers := make([]authz.Provider, 0, len(cfg.Authz.Providers))
	for _, provider := range cfg.Authz.Providers {
		providers = append(providers, buildAuthzProvider(cfg, provider)...)
	}
	return providers
}

func buildAuthzProvider(cfg *config.RouterConfig, provider config.AuthzProviderConfig) []authz.Provider {
	switch provider.Type {
	case "header-injection":
		headerProvider := authz.NewHeaderInjectionProvider(provider.Headers)
		return []authz.Provider{headerProvider}
	case "static-config":
		return []authz.Provider{authz.NewStaticConfigProvider(cfg)}
	default:
		return nil
	}
}

func logValidationErrors(prefix string, validationErrors []string) {
	for _, validationError := range validationErrors {
		logging.Errorf("%s config validation error: %s", prefix, validationError)
	}
}

// buildRateLimitResolver constructs the rate limit provider chain from config.
func buildRateLimitResolver(cfg *config.RouterConfig) *ratelimit.RateLimitResolver {
	rlCfg := cfg.RateLimit

	if len(rlCfg.Providers) == 0 {
		logging.ComponentEvent("extproc", "rate_limit_resolver_disabled", map[string]interface{}{
			"reason": "no_providers_configured",
		})
		return nil
	}

	validationErrors := validateRateLimitProviders(rlCfg.Providers)
	if len(validationErrors) > 0 {
		logValidationErrors("RateLimit", validationErrors)
		logging.Errorf(
			"RateLimit config has %d validation error(s) — rate limiting disabled",
			len(validationErrors),
		)
		return nil
	}

	providers := createRateLimitProviders(rlCfg.Providers)
	if len(providers) == 0 {
		logging.Warnf("RateLimit: no valid providers after construction, rate limiting disabled")
		return nil
	}

	resolver := ratelimit.NewRateLimitResolver(providers...)
	resolver.SetFailOpen(rlCfg.FailOpen)
	if rlCfg.FailOpen {
		logging.Warnf("RateLimit fail_open=true — provider errors will not block requests")
	}
	logging.Infof("RateLimit: chain=%v, fail_open=%v", resolver.ProviderNames(), rlCfg.FailOpen)
	return resolver
}

func validateRateLimitProviders(providers []config.RateLimitProviderConfig) []string {
	validationErrors := make([]string, 0)
	for i, provider := range providers {
		validationErrors = append(validationErrors, validateRateLimitProvider(i, provider)...)
	}
	return validationErrors
}

func validateRateLimitProvider(index int, provider config.RateLimitProviderConfig) []string {
	validationErrors := make([]string, 0)
	if !knownRateLimitProviderTypes[provider.Type] {
		validationErrors = append(
			validationErrors,
			fmt.Sprintf(
				"ratelimit.providers[%d]: unknown type %q (valid types: envoy-ratelimit, local-limiter)",
				index,
				provider.Type,
			),
		)
	}
	if provider.Type == "envoy-ratelimit" && provider.Address == "" {
		validationErrors = append(
			validationErrors,
			fmt.Sprintf("ratelimit.providers[%d]: envoy-ratelimit requires 'address'", index),
		)
	}
	if provider.Type == "local-limiter" && len(provider.Rules) == 0 {
		validationErrors = append(
			validationErrors,
			fmt.Sprintf("ratelimit.providers[%d]: local-limiter requires at least one rule", index),
		)
	}
	return validationErrors
}

func createRateLimitProviders(providersCfg []config.RateLimitProviderConfig) []ratelimit.Provider {
	providers := make([]ratelimit.Provider, 0, len(providersCfg))
	for _, providerCfg := range providersCfg {
		provider := buildRateLimitProvider(providerCfg)
		if provider != nil {
			providers = append(providers, provider)
		}
	}
	return providers
}

func buildRateLimitProvider(providerCfg config.RateLimitProviderConfig) ratelimit.Provider {
	switch providerCfg.Type {
	case "envoy-ratelimit":
		return buildEnvoyRateLimitProvider(providerCfg)
	case "local-limiter":
		return buildLocalRateLimitProvider(providerCfg)
	default:
		return nil
	}
}

package classification

import (
	"fmt"
	"time"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
)

// SignalEvaluationInput is the complete, typed input to request-time signal
// evaluation. Keeping optional values named avoids positional interface{}
// arguments and makes new signal context additive without changing call order.
type SignalEvaluationInput struct {
	Text                   string
	ContextText            string
	CurrentUserText        string
	PriorUserMessages      []string
	NonUserMessages        []string
	HasPriorAssistantReply bool
	Headers                map[string]string
	ForceEvaluateAll       bool
	ImageURL               string
	UncompressedText       string
	SkipCompressionSignals map[string]bool
	ConversationFacts      ConversationFacts
	RequestFacts           RequestFacts
}

// EvaluateAllSignalsWithHeaders evaluates the selected recipe's signals,
// including authz role bindings. Authz errors are returned to the caller so a
// missing identity cannot silently bypass policy.
func (c *Classifier) EvaluateAllSignalsWithHeaders(input SignalEvaluationInput) (*SignalResults, error) {
	results := c.evaluateAllSignalsWithContext(
		input.Text,
		input.ContextText,
		input.CurrentUserText,
		input.PriorUserMessages,
		input.NonUserMessages,
		input.HasPriorAssistantReply,
		input.ForceEvaluateAll,
		input.UncompressedText,
		input.SkipCompressionSignals,
		input.ConversationFacts,
		input.ImageURL,
		input.RequestFacts,
		nil,
		false,
	)
	if err := c.appendAuthzFromHeaders(results, input.Headers, input.ForceEvaluateAll); err != nil {
		return nil, err
	}
	return results, nil
}

func (c *Classifier) appendAuthzFromHeaders(results *SignalResults, headers map[string]string, forceEvaluateAll bool) error {
	usedSignals := c.getUsedSignals()
	if forceEvaluateAll {
		usedSignals = c.getAllSignalTypes()
	}
	if !isSignalTypeUsed(usedSignals, config.SignalTypeAuthz) {
		logging.Debugf("[Signal Computation] Authz signal not used in any decision, skipping evaluation")
		return nil
	}
	if c.authzClassifier == nil {
		return nil
	}

	start := time.Now()
	userID := headers[c.authzUserIDHeader]
	userGroups := ParseUserGroups(headers[c.authzUserGroupsHeader])

	authzResult, err := c.authzClassifier.Classify(userID, userGroups)
	authzResult, err = applyAuthzFailOpenOnClassifyError(c.authzFailOpen, userID, authzResult, err)
	elapsed := time.Since(start)
	latencySeconds := elapsed.Seconds()

	results.Metrics.Authz.ExecutionTimeMs = float64(elapsed.Microseconds()) / 1000.0
	results.Metrics.Authz.Confidence = 1.0

	if err != nil {
		logging.Errorf("[Authz Signal] classification failed: %v", err)
		c.recordSignalExtraction(config.SignalTypeAuthz, "error", latencySeconds)
		return fmt.Errorf("authz signal evaluation failed: %w", err)
	}

	for _, ruleName := range authzResult.MatchedRules {
		c.recordSignalExtraction(config.SignalTypeAuthz, ruleName, latencySeconds)
		c.recordSignalMatch(config.SignalTypeAuthz, ruleName)
	}
	results.MatchedAuthzRules = authzResult.MatchedRules
	logging.Debugf("[Signal Computation] Authz signal evaluation completed in %v", elapsed)
	return nil
}

func (r *OpenAIRouter) runRequestPreRoutingStages(
	originalModel string,
	fast *FastExtractResult,
	ctx *RequestContext,
) (requestDecisionState, *ext_proc.ProcessingResponse) {
	r.resolveEntrypointForRequest(originalModel, ctx)
	populatePinnedSessionFromHeaders(ctx)
	history := signalConversationHistoryFromFastExtract(fast)
	decisionName, _, reasoningDecision, selectedModel, decisionErr := r.performDecisionEvaluation(
		originalModel,
		history,
		ctx,
	)
	if decisionErr != nil {
		if errors.Is(decisionErr, context.Canceled) ||
			errors.Is(decisionErr, context.DeadlineExceeded) {
			return requestDecisionState{}, r.createErrorResponse(499, "request canceled")
		}
		logging.Errorf("[Request Body] Authz evaluation failed: %v", decisionErr)
		return requestDecisionState{}, r.createErrorResponse(403, decisionErr.Error())
	}

	metrics.RecordModelRequest(selectedModel)
	ctx.InflightToken = inflight.Begin(selectedModel)
	if resp := r.handleFastResponse(ctx, decisionName); resp != nil {
		inflight.End(selectedModel, ctx.InflightToken)
		ctx.InflightToken = 0
		r.startRouterReplay(ctx, originalModel, selectedModel, decisionName)
		r.updateRouterReplayStatus(ctx, 200, false)
		r.attachRouterReplayResponse(
			ctx,
			resp.GetImmediateResponse().GetBody(),
			true,
		)
		addRouterReplayHeaderToImmediateResponse(resp, ctx.RouterReplayID)
		return requestDecisionState{}, resp
	}
	if resp := r.applyRateLimitAndCacheChecks(ctx, selectedModel, decisionName); resp != nil {
		inflight.End(selectedModel, ctx.InflightToken)
		ctx.InflightToken = 0
		return requestDecisionState{}, resp
	}
	if ragErr := r.executeRAGPlugin(ctx, decisionName); ragErr != nil {
		inflight.End(selectedModel, ctx.InflightToken)
		ctx.InflightToken = 0
		return requestDecisionState{}, r.createErrorResponse(503, fmt.Sprintf("RAG retrieval failed: %v", ragErr))
	}

	return requestDecisionState{
		decisionName:      decisionName,
		reasoningDecision: reasoningDecision,
		selectedModel:     selectedModel,
	}, nil
}

