301	func (r *OpenAIRouter) createRateLimitResponse(decision *ratelimit.Decision) *ext_proc.ProcessingResponse {
302		retryAfterSec := "60"
303		if decision != nil && decision.RetryAfter > 0 {
304			retryAfterSec = fmt.Sprintf("%d", int(decision.RetryAfter.Seconds()))
305		}
306	
307		body := []byte(fmt.Sprintf(`{"error":{"message":"Rate limit exceeded. Retry after %s seconds.","type":"rate_limit_error","code":429}}`, retryAfterSec))
308	
309		respHeaders := []*core.HeaderValueOption{
310			{Header: &core.HeaderValue{Key: "content-type", RawValue: []byte("application/json")}},
311			{Header: &core.HeaderValue{Key: "retry-after", RawValue: []byte(retryAfterSec)}},
312		}
313	
314		if decision != nil {
315			respHeaders = append(respHeaders,
316				&core.HeaderValueOption{Header: &core.HeaderValue{
317					Key: "x-ratelimit-limit", RawValue: []byte(fmt.Sprintf("%d", decision.Limit)),
318				}},
319				&core.HeaderValueOption{Header: &core.HeaderValue{
320					Key: "x-ratelimit-remaining", RawValue: []byte(fmt.Sprintf("%d", decision.Remaining)),
321				}},
322			)
323			if !decision.ResetAt.IsZero() {
324				respHeaders = append(respHeaders, &core.HeaderValueOption{Header: &core.HeaderValue{
325					Key: "x-ratelimit-reset", RawValue: []byte(fmt.Sprintf("%d", decision.ResetAt.Unix())),
326				}})
327			}
328		}
329	
330		// v0.4 keystone headers: this is the rate-limit path (#2203).
331		respHeaders = append(respHeaders, httputil.KeystoneHeaderOptions(headers.ResponsePathRateLimited)...)
332	
333		return &ext_proc.ProcessingResponse{
334			Response: &ext_proc.ProcessingResponse_ImmediateResponse{
335				ImmediateResponse: &ext_proc.ImmediateResponse{
336					Status: &typev3.HttpStatus{Code: typev3.StatusCode_TooManyRequests},
337					Headers: &ext_proc.HeaderMutation{
338						SetHeaders: respHeaders,
339					},
340					Body: body,
341				},
342			},
343		}
344	}
